-- SQLite-only projection of reviewed v1.11 schema. Never run against SQL Server.
CREATE TABLE ntf__NotificationChannelStatuses(StatusCode TEXT PRIMARY KEY NOT NULL,DisplayName TEXT NOT NULL,IsOperational INTEGER NOT NULL CHECK(IsOperational IN(0,1)));
CREATE TABLE ntf__NotificationChannels(ChannelId INTEGER PRIMARY KEY AUTOINCREMENT,ChannelCode TEXT NOT NULL UNIQUE,DisplayName TEXT NOT NULL,IsEnabled INTEGER NOT NULL DEFAULT 0 CHECK(IsEnabled IN(0,1)),StatusCode TEXT NOT NULL REFERENCES ntf__NotificationChannelStatuses(StatusCode),RowVersion BLOB NOT NULL DEFAULT(randomblob(8)) CHECK(length(RowVersion)=8));
CREATE TABLE ntf__NotificationTemplateTypes(TemplateCode TEXT PRIMARY KEY NOT NULL,DisplayName TEXT NOT NULL,IsEnabled INTEGER NOT NULL DEFAULT 0 CHECK(IsEnabled IN(0,1)));
CREATE TABLE ntf__NotificationTemplateStatuses(StatusCode TEXT PRIMARY KEY NOT NULL,DisplayName TEXT NOT NULL,IsTerminal INTEGER NOT NULL CHECK(IsTerminal IN(0,1)));
CREATE TABLE ntf__NotificationVariableDefinitions(TemplateCode TEXT NOT NULL REFERENCES ntf__NotificationTemplateTypes(TemplateCode),VariableCode TEXT NOT NULL,DisplayName TEXT NOT NULL,DataTypeCode TEXT NOT NULL,IsRequired INTEGER NOT NULL CHECK(IsRequired IN(0,1)),PRIMARY KEY(TemplateCode,VariableCode));
CREATE TABLE ntf__NotificationTemplates(TemplateId TEXT PRIMARY KEY NOT NULL DEFAULT(lower(hex(randomblob(16)))),TemplateCode TEXT NOT NULL REFERENCES ntf__NotificationTemplateTypes(TemplateCode),DisplayName TEXT NOT NULL,ChannelId INTEGER NOT NULL REFERENCES ntf__NotificationChannels(ChannelId),LocaleCode TEXT NOT NULL,CreatedByUserId INTEGER NOT NULL REFERENCES iam__Users(UserId),CreatedAtUtc TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),RowVersion BLOB NOT NULL DEFAULT(randomblob(8)) CHECK(length(RowVersion)=8),UNIQUE(TemplateCode,ChannelId,LocaleCode),UNIQUE(TemplateId,TemplateCode));
CREATE TABLE ntf__NotificationTemplateVersions(TemplateVersionId TEXT PRIMARY KEY NOT NULL DEFAULT(lower(hex(randomblob(16)))),TemplateId TEXT NOT NULL REFERENCES ntf__NotificationTemplates(TemplateId),TemplateCode TEXT NOT NULL,VersionNumber INTEGER NOT NULL CHECK(VersionNumber>0),StatusCode TEXT NOT NULL REFERENCES ntf__NotificationTemplateStatuses(StatusCode),Subject TEXT NOT NULL CHECK(length(rtrim(Subject))>0),Body TEXT NOT NULL CHECK(length(rtrim(Body))>0),CreatedByUserId INTEGER NOT NULL REFERENCES iam__Users(UserId),CreatedAtUtc TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),SubmittedAtUtc TEXT,ActivatedAtUtc TEXT,ArchivedAtUtc TEXT,RowVersion BLOB NOT NULL DEFAULT(randomblob(8)) CHECK(length(RowVersion)=8),UNIQUE(TemplateId,VersionNumber),UNIQUE(TemplateVersionId,TemplateCode),FOREIGN KEY(TemplateId,TemplateCode) REFERENCES ntf__NotificationTemplates(TemplateId,TemplateCode));
CREATE UNIQUE INDEX UX_NotificationTemplateVersions_OneActive ON ntf__NotificationTemplateVersions(TemplateId) WHERE StatusCode='ACTIVE';
CREATE TABLE ntf__NotificationTemplateVersionVariables(TemplateVersionId TEXT NOT NULL,TemplateCode TEXT NOT NULL,VariableCode TEXT NOT NULL,IsRequired INTEGER NOT NULL CHECK(IsRequired IN(0,1)),PRIMARY KEY(TemplateVersionId,VariableCode),FOREIGN KEY(TemplateVersionId,TemplateCode) REFERENCES ntf__NotificationTemplateVersions(TemplateVersionId,TemplateCode),FOREIGN KEY(TemplateCode,VariableCode) REFERENCES ntf__NotificationVariableDefinitions(TemplateCode,VariableCode));
CREATE TABLE ntf__NotificationTemplateApprovals(ApprovalId INTEGER PRIMARY KEY AUTOINCREMENT,TemplateVersionId TEXT NOT NULL REFERENCES ntf__NotificationTemplateVersions(TemplateVersionId),ActorUserId INTEGER NOT NULL REFERENCES iam__Users(UserId),DecisionCode TEXT NOT NULL CHECK(DecisionCode IN('APPROVE','REJECT')),DecisionNote TEXT,DecidedAtUtc TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE ntf__NotificationDeliveryOutcomes(OutcomeCode TEXT PRIMARY KEY NOT NULL,DisplayName TEXT NOT NULL);
CREATE TABLE ntf__NotificationErrorCategories(ErrorCategoryCode TEXT PRIMARY KEY NOT NULL,DisplayName TEXT NOT NULL);
CREATE TABLE ntf__NotificationDeliveries(DeliveryId TEXT PRIMARY KEY NOT NULL DEFAULT(lower(hex(randomblob(16)))),TemplateVersionId TEXT REFERENCES ntf__NotificationTemplateVersions(TemplateVersionId),TemplateCodeSnapshot TEXT NOT NULL,TemplateVersionSnapshot INTEGER CHECK(TemplateVersionSnapshot IS NULL OR TemplateVersionSnapshot>0),ChannelId INTEGER NOT NULL REFERENCES ntf__NotificationChannels(ChannelId),CorrelationId TEXT NOT NULL,CreatedAtUtc TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IX_NotificationDeliveries_Correlation ON ntf__NotificationDeliveries(CorrelationId,CreatedAtUtc DESC);
CREATE TABLE ntf__NotificationDeliveryAttempts(AttemptId INTEGER PRIMARY KEY AUTOINCREMENT,DeliveryId TEXT NOT NULL REFERENCES ntf__NotificationDeliveries(DeliveryId),AttemptNumber INTEGER NOT NULL CHECK(AttemptNumber>0),OutcomeCode TEXT NOT NULL REFERENCES ntf__NotificationDeliveryOutcomes(OutcomeCode),ErrorCategoryCode TEXT REFERENCES ntf__NotificationErrorCategories(ErrorCategoryCode),OccurredAtUtc TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),ProviderAccepted INTEGER NOT NULL CHECK(ProviderAccepted IN(0,1)),UNIQUE(DeliveryId,AttemptNumber),CHECK((ProviderAccepted=1 AND OutcomeCode='PROVIDER_ACCEPTED' AND ErrorCategoryCode IS NULL) OR (ProviderAccepted=0 AND OutcomeCode='PROVIDER_REJECTED' AND ErrorCategoryCode IS NOT NULL)));
CREATE TRIGGER trg_NotificationTemplateVersions_ActiveImmutable BEFORE UPDATE ON ntf__NotificationTemplateVersions WHEN OLD.StatusCode IN('ACTIVE','ARCHIVED') AND (NEW.TemplateVersionId IS NOT OLD.TemplateVersionId OR NEW.TemplateId IS NOT OLD.TemplateId OR NEW.TemplateCode IS NOT OLD.TemplateCode OR NEW.VersionNumber IS NOT OLD.VersionNumber OR NEW.Subject IS NOT OLD.Subject OR NEW.Body IS NOT OLD.Body OR NEW.CreatedByUserId IS NOT OLD.CreatedByUserId OR NEW.CreatedAtUtc IS NOT OLD.CreatedAtUtc OR NEW.SubmittedAtUtc IS NOT OLD.SubmittedAtUtc OR NEW.ActivatedAtUtc IS NOT OLD.ActivatedAtUtc OR (OLD.StatusCode='ACTIVE' AND (NEW.StatusCode NOT IN('ACTIVE','ARCHIVED') OR (NEW.StatusCode='ACTIVE' AND NEW.ArchivedAtUtc IS NOT OLD.ArchivedAtUtc) OR (NEW.StatusCode='ARCHIVED' AND NEW.ArchivedAtUtc IS NULL))) OR (OLD.StatusCode='ARCHIVED' AND (NEW.StatusCode<>'ARCHIVED' OR NEW.ArchivedAtUtc IS NOT OLD.ArchivedAtUtc))) BEGIN SELECT RAISE(ABORT,'Active and archived versions immutable'); END;
CREATE TRIGGER trg_NotificationTemplateVersions_ActiveDelete BEFORE DELETE ON ntf__NotificationTemplateVersions WHEN OLD.StatusCode IN('ACTIVE','ARCHIVED') BEGIN SELECT RAISE(ABORT,'Active and archived versions cannot be deleted'); END;
